package vn.iotstar.controller.admin;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import vn.iotstar.entity.User;import vn.iotstar.service.UserService;import vn.iotstar.service.impl.UserServiceImpl;import java.io.IOException;import java.util.List;
@WebServlet("/admin/account/list") public class AccountListController extends HttpServlet{private final UserService s=new UserServiceImpl();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{if(!AdminAuth.requireAdmin(r,p))return;String k=r.getParameter("keyword");List<User> list=(k==null||k.isBlank())?s.findAll():s.search(k.trim());r.setAttribute("accounts",list);r.setAttribute("keyword",k==null?"":k);r.getRequestDispatcher("/views/admin/list-account.jsp").forward(r,p);}}
